import { FormEvent, useEffect, useState } from "react";
import { api } from "./api";
import type { AssessmentState, PipelineSection, PipelineSnapshot } from "./types";

type System = { key: string; label: string; project_key: string; available: boolean };
type Summary = { label: string; built_at_utc?: string; index_complete: boolean; current_captures: number; files_by_status: Record<string, number>; evidence_rows: number; families: string[]; coverage: { host: string; families: Record<string, number> }[] };
type EvidenceRow = Record<string, string>;
type FileRow = { file_id: number; rel_path: string; host?: string; ext: string; size: number; status: string; reason?: string; source_class: string; current: number };
type IndexHit = { file_id?: number; source_title: string; source_version: string; page_or_location: string; evidence_excerpt: string; rel_path: string; host?: string; superseded: boolean };
type SearchStage = { kind: "matrix" | "index"; verdict?: string; matches?: EvidenceRow[]; results?: IndexHit[] };
type SearchResponse = { query: string; stages: SearchStage[] };
type TableInfo = { table: string; rows: number; hosts: number; columns: string[] };
type Preview = { kind: string; name: string; rel_path: string; lines?: { number: number; text: string }[]; highlight?: [number, number]; rows?: string[][]; row_start?: number; highlight_row?: number; pdf_url?: string; raw_url?: string; reason?: string };
type Draft = { csa_area: string; question: string; claim: string; status: string; source_title: string; source_version: string; section: string; page_or_location: string; evidence_excerpt: string; inference_reason: string; confidence: string; gap_or_action: string; review_state: string };
type Area = { key: string; label: string; state: string; total: number; counts: Record<string, number>; pending_review: number; claims: EvidenceRow[]; decisions: EvidenceRow[] };
type Portrait = {
  application: { name: string; system: string; project_key: string; scope: string };
  assessment: { total: number; status_counts: Record<string, number>; review_counts: Record<string, number> };
  areas: Area[]; attention: EvidenceRow[];
  observed_hosts: { host: string; families: Record<string, number>; files: number; breadth: number }[];
  source_health: { files: number; status_counts: Record<string, number>; skipped_reasons: { reason: string; count: number }[] };
  disclaimer: string;
};
type DocumentInfo = { state: string; reason?: string; candidates?: string[]; filename?: string; path?: string; size?: number; modified_at?: string; properties?: Record<string, string>; word_locked?: boolean; word_lock_file?: string; tracked_changes?: { insertions: number; deletions: number; total: number }; comment_count?: number; manifest?: { state: string; path?: string } };
type DocumentPreview = { state: string; reason?: string; filename?: string; cache_key?: string; page_count?: number; pdf_url?: string; revision_url?: string; revisions_in_pdf?: boolean; comments_in_pdf?: boolean };
type RevisionView = { filename: string; notice: string; sections: { index: number; title: string }[]; paragraphs: { index: number; style: string; tokens: { kind: string; text: string }[] }[] };
type DocumentComment = { id: string; author: string; date?: string; text: string; anchored_text: string };
type SectionInspection = { identity: { requested: string; visible_number: string; stable_key: string; stable_path?: string; stable_id?: string; heading: string; kind: string }; current: { status: { open?: number; total?: number; state?: string }; parts: any[] }; requirements: { id: string; text: string; current_state: string; rating: string; table_id?: string }[]; comments: { author: string; text: string; facet?: string }[]; guidance: { author: string; text: string; facet?: string }[]; removed: { paragraph_id?: number; text: string }[]; evidence: EvidenceRow[]; questions: { id?: string; question: string; answered: boolean }[]; open_questions: { id?: string; question: string; answered: boolean }[]; work: { lane: string; change_file?: string; section_file?: string; proposal?: string; author_report: Record<string, unknown> }; validation: { state: string; findings: string[] } };
type ProposalRecord = { edit_id: string; title: string; target: string; operation: string; replacement: string; facts: string; rationale: string; note: string; evidence_ids: string[] };
type ProposalFile = { section: { visible_number: string; stable_key: string; heading: string; stable_id: string }; lane: "revise" | "build"; file: string; etag: string; approved: boolean; approval_warning?: string; stable_ids: string[]; next_edit_id: string; records: ProposalRecord[]; content?: string };
type ValidationFinding = { severity: string; code: string; edit_id?: string; record_id?: string; field?: string; stable_anchor?: string; evidence_ids: string[]; message: string };
type ValidationResult = { file: string; file_hash: string; operation: string; valid: boolean; stale: boolean; errors: number; warnings: number; findings: ValidationFinding[] };
type ApplyPlan = { system: string; section: { visible_number: string; heading: string }; proposal: string; proposal_hash: string; document: string; edit_count: number; edit_ids: string[] };
type ApplyJob = { id: string; state: string; stdout_tail?: string; stderr_tail?: string; message?: string };
type ApplyOutcome = { state: string; applied: string[]; already_applied: string[]; skipped: string[]; blocked: string[]; backup?: string; warnings: string[]; next_edit_id?: string };
type View = "portrait" | "assessment" | "evidence" | "sources" | "tables";

const STATUSES = ["VERIFIED", "INFERRED", "UNCONFIRMED", "CONFLICTING", "NOT_FOUND"];
const EMPTY_DRAFT: Draft = { csa_area: "", question: "", claim: "", status: "VERIFIED", source_title: "", source_version: "", section: "", page_or_location: "", evidence_excerpt: "", inference_reason: "", confidence: "high", gap_or_action: "", review_state: "pending" };
const NAV: { id: View; title: string; note: string }[] = [
  { id: "portrait", title: "Application portrait", note: "What the evidence says" },
  { id: "assessment", title: "Assessment", note: "Read the working document" },
  { id: "evidence", title: "Claims and gaps", note: "What can be stated" },
  { id: "sources", title: "Source coverage", note: "What was observed" },
  { id: "tables", title: "Explore records", note: "Compare across hosts" },
];

function human(value = "") { return value.replaceAll("_", " ").replace(/\b\w/g, c => c.toUpperCase()); }
function bytes(value: number) { return value < 1000 ? `${value} B` : value < 1e6 ? `${(value / 1000).toFixed(1)} KB` : `${(value / 1e6).toFixed(1)} MB`; }
function Status({ value }: { value?: string }) { const name = (value || "unknown").toLowerCase().replaceAll("_", " "); return <span className={`status status-${name.replaceAll(" ", "-")}`}>{name}</span>; }

export default function App() {
  const [systems, setSystems] = useState<System[]>([]);
  const [system, setSystem] = useState(new URLSearchParams(location.search).get("system") || "iamps");
  const [view, setView] = useState<View>("portrait"); const [summary, setSummary] = useState<Summary | null>(null); const [portrait, setPortrait] = useState<Portrait | null>(null);
  const [evidence, setEvidence] = useState<EvidenceRow[]>([]); const [files, setFiles] = useState<FileRow[]>([]); const [fileTotal, setFileTotal] = useState(0);
  const [facets, setFacets] = useState<{ statuses: string[]; extensions: string[]; source_classes: string[] }>({ statuses: [], extensions: [], source_classes: [] });
  const [tables, setTables] = useState<TableInfo[]>([]); const [tableRows, setTableRows] = useState<Record<string, unknown>[] | null>(null); const [activeTable, setActiveTable] = useState("");
  const [query, setQuery] = useState(""); const [search, setSearch] = useState<SearchResponse | null>(null); const [busy, setBusy] = useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const [preview, setPreview] = useState<Preview | null>(null); const [draft, setDraft] = useState<Draft | null>(null); const [draftResult, setDraftResult] = useState<Record<string, unknown> | null>(null);
  const [choices, setChoices] = useState<{ row: EvidenceRow; files: FileRow[] } | null>(null);
  const [documentInfo, setDocumentInfo] = useState<DocumentInfo | null>(null); const [documentPreview, setDocumentPreview] = useState<DocumentPreview | null>(null); const [revisionView, setRevisionView] = useState<RevisionView | null>(null); const [documentComments, setDocumentComments] = useState<DocumentComment[]>([]);
  const [pipeline, setPipeline] = useState<PipelineSnapshot | null>(null); const [selectedSection, setSelectedSection] = useState<PipelineSection | null>(null); const [sectionInspection, setSectionInspection] = useState<SectionInspection | null>(null); const [showDocument, setShowDocument] = useState(false);
  const [fileQuery, setFileQuery] = useState(""); const [fileStatus, setFileStatus] = useState(""); const [fileExt, setFileExt] = useState(""); const [fileClass, setFileClass] = useState(""); const [history, setHistory] = useState(false);

  useEffect(() => { api<{ systems: System[] }>("/api/systems").then(x => setSystems(x.systems)).catch(e => setError(e.message)); }, []);
  useEffect(() => {
    window.history.replaceState(null, "", `?system=${system}`); setLoading(true); setError(""); setSearch(null); setPreview(null); setDocumentInfo(null); setDocumentPreview(null); setRevisionView(null); setDocumentComments([]);
    Promise.all([
      api<Summary>(`/api/systems/${system}/summary`), api<Portrait>(`/api/systems/${system}/portrait`),
      api<{ rows: EvidenceRow[] }>(`/api/systems/${system}/evidence?limit=500`),
      api<{ files: FileRow[]; total: number; facets: typeof facets }>(`/api/systems/${system}/files?limit=500`),
      api<{ tables: TableInfo[] }>(`/api/systems/${system}/tables`),
    ]).then(([s, p, e, f, t]) => { setSummary(s); setPortrait(p); setEvidence(e.rows); setFiles(f.files); setFileTotal(f.total); setFacets(f.facets); setTables(t.tables); })
      .catch(e => setError(e.message)).finally(() => setLoading(false));
  }, [system]);
  useEffect(() => { const timer = window.setTimeout(() => { const p = new URLSearchParams({ limit: "500", all_captures: String(history), include_archive: String(history) }); if (fileQuery) p.set("q", fileQuery); if (fileStatus) p.set("status", fileStatus); if (fileExt) p.set("ext", fileExt); if (fileClass) p.set("source_class", fileClass); api<{ files: FileRow[]; total: number; facets: typeof facets }>(`/api/systems/${system}/files?${p}`).then(x => { setFiles(x.files); setFileTotal(x.total); setFacets(x.facets); }).catch(e => setError(e.message)); }, 180); return () => clearTimeout(timer); }, [system, history, fileQuery, fileStatus, fileExt, fileClass]);

  async function runSearch(text: string) { if (!text.trim()) return; setQuery(text); setBusy(true); setError(""); try { setSearch(await api<SearchResponse>(`/api/systems/${system}/search`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ query: text }) })); } catch (e) { setError((e as Error).message); } finally { setBusy(false); } }
  function submit(event: FormEvent) { event.preventDefault(); void runSearch(query); }
  async function openFile(id: number, anchor = "") { try { setPreview(await api<Preview>(`/api/systems/${system}/files/${id}/preview?anchor=${encodeURIComponent(anchor)}`)); } catch (e) { setError((e as Error).message); } }
  async function openEvidence(row: EvidenceRow) { try { const result = await api<{ sources: FileRow[] }>(`/api/systems/${system}/evidence/${row.evidence_id}/sources`); if (result.sources.length === 1) await openFile(result.sources[0].file_id, row.page_or_location); else if (!result.sources.length) setError(`Source unavailable for ${row.evidence_id}. The claim is recorded, but its cited file is not in the current index.`); else setChoices({ row, files: result.sources }); } catch (e) { setError((e as Error).message); } }
  function byId(id: string) { return evidence.find(row => row.evidence_id === id) || { evidence_id: id }; }
  function prepare(hit: IndexHit) { setDraft({ ...EMPTY_DRAFT, question: search?.query || "", source_title: hit.source_title, source_version: hit.source_version, page_or_location: hit.page_or_location, evidence_excerpt: hit.evidence_excerpt }); setDraftResult(null); }
  async function validateDraft() { if (!draft) return; try { setDraftResult(await api(`/api/systems/${system}/evidence-drafts/validate`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(draft) })); } catch (e) { setError((e as Error).message); } }
  async function commitDraft() { if (!draft || !draftResult || !confirm("Add this reviewed claim to the append-only evidence matrix?")) return; try { setDraftResult(await api(`/api/systems/${system}/evidence-drafts/commit`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ draft, confirmed: true }) })); setEvidence((await api<{ rows: EvidenceRow[] }>(`/api/systems/${system}/evidence?limit=500`)).rows); } catch (e) { setError((e as Error).message); } }
  async function openTable(name: string) { setActiveTable(name); try { setTableRows((await api<{ results: { row: Record<string, unknown> }[] }>(`/api/systems/${system}/tables?table=${encodeURIComponent(name)}&limit=100`)).results.map(x => x.row)); } catch (e) { setError((e as Error).message); } }
  async function loadAssessment() { try { const info = await api<DocumentInfo>(`/api/systems/${system}/document`); setDocumentInfo(info); if (info.state === "ready") { const [descriptor, revisions, comments] = await Promise.allSettled([api<DocumentPreview>(`/api/systems/${system}/document/preview`), api<RevisionView>(`/api/systems/${system}/document/preview?mode=revisions`), api<{ comments: DocumentComment[] }>(`/api/systems/${system}/document/comments`)]); setDocumentPreview(descriptor.status === "fulfilled" ? descriptor.value : { state: "unavailable", reason: descriptor.reason instanceof Error ? descriptor.reason.message : "Rendered page preview unavailable" }); if (revisions.status === "fulfilled") setRevisionView(revisions.value); if (comments.status === "fulfilled") setDocumentComments(comments.value.comments); } } catch (e) { setError((e as Error).message); } }
  async function selectAssessmentSection(section: PipelineSection | null) { setSelectedSection(section); setSectionInspection(null); if (!section) return; try { setSectionInspection(await api<SectionInspection>(`/api/systems/${system}/sections/${encodeURIComponent(section.stable_key || section.visible_number)}`)); } catch (e) { setError((e as Error).message); } }
  useEffect(() => { if (view !== "assessment") return; let current = true; setPipeline(null); setSelectedSection(null); api<PipelineSnapshot>(`/api/systems/${system}/pipeline`).then(value => { if (current) setPipeline(value); }).catch(e => { if (current) setError(e.message); }); return () => { current = false; }; }, [view, system]);
  useEffect(() => { if (view === "assessment" && showDocument && !documentInfo) void loadAssessment(); }, [view, system, showDocument]);
  function switchSystem(next: string) { setSelectedSection(null); setPipeline(null); setShowDocument(false); setPreview(null); setDocumentInfo(null); setDocumentPreview(null); setRevisionView(null); setDocumentComments([]); setTableRows(null); setActiveTable(""); setDraft(null); setChoices(null); setSystem(next); }
  const matrix = search?.stages.find(x => x.kind === "matrix"); const index = search?.stages.find(x => x.kind === "index");

  return <div className="shell">
    <header className="masthead"><button className="product-mark" onClick={() => { setSearch(null); setView("portrait"); }}><span className="mark-lines" /><span><b>CSA evidence</b><small>Application assessment workspace</small></span></button>
      <label className="system-picker"><span>Application</span><select value={system} onChange={e => switchSystem(e.target.value)}>{systems.map(x => <option key={x.key} value={x.key} disabled={!x.available}>{x.label}</option>)}</select></label>
      <form className="global-search" onSubmit={submit}><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Ask about the application, host, service or control" aria-label="Trace evidence" /><button disabled={busy}>{busy ? "Tracing…" : "Trace evidence"}</button></form>
    </header>
    <aside className="rail"><div className="rail-app"><span>Assessing</span><strong>{portrait?.application.name || summary?.label || "Application"}</strong><small>within {portrait?.application.system || "the selected system"}</small></div><nav>{NAV.map(x => <button key={x.id} className={view === x.id && !search ? "active" : ""} onClick={() => { setView(x.id); setSearch(null); }}><span>{x.title}</span><small>{x.note}</small></button>)}</nav><div className="rail-note"><i className={summary?.index_complete ? "lamp good" : "lamp"} /><div>{summary?.index_complete ? "Sources ready" : "Index incomplete"}<small>{summary?.built_at_utc ? `Indexed ${summary.built_at_utc.slice(0, 10)}` : "Build date unavailable"}</small></div></div></aside>
    <main className="workspace">{error && <div className="error" role="alert"><div><b>Action needed</b><span>{error}</span></div><button onClick={() => setError("")}>×</button></div>}{loading ? <Loading /> : search ? <SearchDesk data={search} matrix={matrix} index={index} openFile={openFile} openEvidence={openEvidence} prepare={prepare} close={() => setSearch(null)} /> : view === "portrait" ? <ApplicationPortrait portrait={portrait} summary={summary} openEvidence={id => openEvidence(byId(id))} investigate={runSearch} navigate={setView} /> : view === "assessment" ? showDocument ? <AssessmentReader info={documentInfo} preview={documentPreview} revisions={revisionView} comments={documentComments} reload={loadAssessment} back={() => setShowDocument(false)} /> : <AssessmentShell snapshot={pipeline} selected={selectedSection} inspection={sectionInspection} select={selectAssessmentSection} openEvidence={openEvidence} refresh={async () => { setPipeline(await api<PipelineSnapshot>(`/api/systems/${system}/pipeline`)); await loadAssessment(); }} readDocument={() => setShowDocument(true)} /> : view === "evidence" ? <EvidenceLedger rows={evidence} areas={portrait?.areas || []} openEvidence={openEvidence} investigate={runSearch} /> : view === "sources" ? <SourceCoverage summary={summary} portrait={portrait} files={files} total={fileTotal} facets={facets} controls={{ fileQuery, fileStatus, fileExt, fileClass, history, setFileQuery, setFileStatus, setFileExt, setFileClass, setHistory }} openFile={openFile} /> : <Tables tables={tables} rows={tableRows} active={activeTable} openTable={openTable} />}</main>
    {preview && <SourceReader preview={preview} close={() => setPreview(null)} />}{draft && <DraftPanel draft={draft} setDraft={setDraft} result={draftResult} validate={validateDraft} commit={commitDraft} close={() => setDraft(null)} />}{choices && <SourceChooser row={choices.row} files={choices.files} close={() => setChoices(null)} choose={file => { const row = choices.row; setChoices(null); void openFile(file.file_id, row.page_or_location); }} />}
  </div>;
}

const ASSESSMENT_STATE_LABEL: Record<AssessmentState, string> = {
  "not-started": "Not started", draft: "Draft", "validation-failed": "Validation failed",
  "ready-to-apply": "Ready to apply", "partially-applied": "Partially applied",
  "awaiting-word-decision": "Awaiting Word decision", "review-failed": "Review failed",
  "ready-to-clean": "Ready to clean", complete: "Complete", unknown: "Unknown",
};

export function pipelineState(section: PipelineSection): AssessmentState {
  const validation = section.validation_result.toLowerCase(); const applied = section.applied_state.toLowerCase();
  const review = section.review_verdict.toLowerCase(); const cleanup = section.cleanup_state.toLowerCase();
  if ([validation, applied, review, cleanup, section.lane].some(value => value === "unknown")) return "unknown";
  if (cleanup === "complete") return "complete";
  if (review.includes("fail") || review.includes("block")) return "review-failed";
  if (["pass", "passed", "ready"].includes(review) && cleanup !== "complete") return "ready-to-clean";
  if (["partial", "partially_applied", "partial_complete"].includes(applied)) return "partially-applied";
  if (applied === "complete" && ["not_started", "not-started", "pending"].includes(review)) return "awaiting-word-decision";
  if (validation.includes("fail") || validation.includes("error") || validation.includes("not_ready")) return "validation-failed";
  if (["not_started", "not-started"].includes(applied) && ["valid", "ready", "pass", "passed"].includes(validation)) return "ready-to-apply";
  if (section.change_file || section.section_file) return "draft";
  return "not-started";
}

function exactNext(section: PipelineSection, snapshot: PipelineSnapshot): string {
  if (section.next_action) return section.next_action;
  const next = snapshot.next_action || {}; const target = String(next.section || next.number || "");
  if (target && (target === section.visible_number || section.visible_number.startsWith(target + "."))) return String(next.next || next.command || "Unknown");
  return "Not reported for this section";
}

function metric(value: number | undefined, singular: string, plural = singular + "s") {
  return value === undefined ? "Not reported" : `${value} ${value === 1 ? singular : plural}`;
}

export function AssessmentShell({ snapshot, selected, inspection = null, select, openEvidence = () => {}, refresh = async () => {}, readDocument }: { snapshot: PipelineSnapshot | null; selected: PipelineSection | null; inspection?: SectionInspection | null; select: (section: PipelineSection | null) => void; openEvidence?: (row: EvidenceRow) => void; refresh?: () => Promise<void>; readDocument: () => void }) {
  if (!snapshot) return <section className="page assessment-map"><Loading /></section>;
  const complete = snapshot.sections.filter(section => pipelineState(section) === "complete").length;
  return <section className="page assessment-map"><header className="assessment-map-head"><div><span>Assessment production map</span><h1>{snapshot.project_label}</h1><p>Sections follow the working document. Use this map to decide what needs evidence, correction, application or review next.</p></div><div className="document-identity"><span>Working document</span><strong>{snapshot.document.name || "Identity unresolved"}</strong><small>{snapshot.spec_mode} specification · {complete} of {snapshot.sections.length} complete</small><button onClick={readDocument}>Read assessment and review marks</button></div></header>
    {snapshot.word_locked && <div className="lock-banner" role="status"><strong>Document open in Word</strong><span>{snapshot.word_lock_file || "A Word owner file is present"}. Read-only work can continue; document-changing actions must wait.</span></div>}
    {snapshot.issues.length > 0 && <div className="pipeline-warning" role="status"><strong>Pipeline records need attention</strong><span>{snapshot.issues.map(issue => issue.message).join(" ")}</span></div>}
    <div className="section-ledger" role="list" aria-label="Assessment sections in document order"><header><span>Section</span><span>Production state</span><span>Evidence and work</span><span>Next action</span></header>{snapshot.sections.map(section => { const state = pipelineState(section); return <button role="listitem" aria-label={`${section.visible_number || section.stable_key} ${section.heading}: ${ASSESSMENT_STATE_LABEL[state]}`} key={section.stable_key || section.visible_number} className={`section-line section-${state}${selected?.stable_key === section.stable_key ? " selected" : ""}`} onClick={() => select(section)}><span className="section-name"><b>{section.visible_number || "—"}</b><span><strong>{section.heading}</strong><small>{human(section.lane)} lane · {section.stable_key}</small></span></span><span className="section-state"><i />{ASSESSMENT_STATE_LABEL[state]}</span><span className="section-counts"><span>{metric(section.evidence_count, "evidence item")}</span><span>{metric(section.open_question_count, "open question")}</span><span>{metric(section.proposed_edits, "proposed edit")}</span></span><span className="section-next">{exactNext(section, snapshot)}</span></button>; })}</div>
    {!snapshot.sections.length && <Empty title="Section order is unavailable" text="The document manifest must be restored before the assessment can be managed safely." />}
    {selected && <SectionWorkspace section={selected} snapshot={snapshot} inspection={inspection} openEvidence={openEvidence} refresh={refresh} close={() => select(null)} />}
  </section>;
}

function SectionWorkspace({ section, snapshot, inspection, openEvidence, refresh, close }: { section: PipelineSection; snapshot: PipelineSnapshot; inspection: SectionInspection | null; openEvidence: (row: EvidenceRow) => void; refresh: () => Promise<void>; close: () => void }) {
  const [proposal, setProposal] = useState<ProposalFile | null>(null); const [dirty, setDirty] = useState(false); const [previewMode, setPreviewMode] = useState(false); const [saveMessage, setSaveMessage] = useState(""); const [validationResult, setValidationResult] = useState<ValidationResult | null>(null); const [validating, setValidating] = useState(false);
  const [applyPlan, setApplyPlan] = useState<ApplyPlan | null>(null); const [applyJob, setApplyJob] = useState<ApplyJob | null>(null); const [applyOutcome, setApplyOutcome] = useState<ApplyOutcome | null>(null);
  useEffect(() => { if (!inspection) return; setProposal(null); setDirty(false); setSaveMessage(""); setValidationResult(null); api<ProposalFile>(`/api/systems/${new URLSearchParams(location.search).get("system") || "iamps"}/sections/${encodeURIComponent(inspection.identity.stable_key)}/proposal`).then(setProposal).catch(() => setProposal(null)); }, [inspection?.identity.stable_key]);
  useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (dirty) event.preventDefault(); }; addEventListener("beforeunload", warn); return () => removeEventListener("beforeunload", warn); }, [dirty]);
  if (!inspection) return <aside className="section-workspace section-inspector-loading"><button aria-label="Close section workspace" onClick={close}>×</button><Loading /></aside>;
  const safeClose = () => { if (!dirty || confirm("Discard unsaved proposal changes?")) close(); };
  const invalidate = () => { setDirty(true); setSaveMessage(""); setValidationResult(null); };
  const changeRecord = (index: number, key: keyof ProposalRecord, value: string | string[]) => { if (!proposal) return; const records = proposal.records.map((record, i) => i === index ? { ...record, [key]: value } : record); setProposal({ ...proposal, records }); invalidate(); };
  const addRecord = () => { if (!proposal) return; setProposal({ ...proposal, records: [...proposal.records, { edit_id: proposal.next_edit_id, title: "", target: proposal.stable_ids[0] || "", operation: "Replace", replacement: "", facts: "", rationale: "", note: "", evidence_ids: [] }] }); invalidate(); };
  const saveProposal = async () => { if (!proposal) return; try { const result = await api<{ etag: string; message: string }>(`/api/systems/${new URLSearchParams(location.search).get("system") || "iamps"}/sections/${encodeURIComponent(inspection.identity.stable_key)}/proposal`, { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify(proposal) }); setProposal({ ...proposal, etag: result.etag, approved: false, approval_warning: undefined }); setDirty(false); setValidationResult(null); setSaveMessage(result.message); } catch (error) { setSaveMessage((error as Error).message); } };
  const validateProposal = async () => { if (!proposal || dirty) return; setValidating(true); setSaveMessage(""); try { const result = await api<ValidationResult>(`/api/systems/${new URLSearchParams(location.search).get("system") || "iamps"}/sections/${encodeURIComponent(inspection.identity.stable_key)}/validate`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ etag: proposal.etag, file: proposal.file }) }); setValidationResult(result); setSaveMessage(result.valid ? `Validation passed with ${result.warnings} warning${result.warnings === 1 ? "" : "s"}.` : `Validation found ${result.errors} error${result.errors === 1 ? "" : "s"}.`); } catch (error) { setValidationResult(null); setSaveMessage((error as Error).message); } finally { setValidating(false); } };
  const prepareApply = async () => { if (!proposal || !validationResult?.valid) return; try { setApplyPlan(await api<ApplyPlan>(`/api/systems/${new URLSearchParams(location.search).get("system") || "iamps"}/sections/${encodeURIComponent(inspection.identity.stable_key)}/apply-preflight`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ file: proposal.file, file_hash: proposal.etag }) })); } catch (error) { setSaveMessage((error as Error).message); } };
  const confirmApply = async () => { if (!proposal || !applyPlan) return; try { const result = await api<{ job: ApplyJob }>(`/api/systems/${new URLSearchParams(location.search).get("system") || "iamps"}/sections/${encodeURIComponent(inspection.identity.stable_key)}/apply`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ file: proposal.file, file_hash: proposal.etag, confirmed: true }) }); setApplyPlan(null); setApplyJob(result.job); } catch (error) { setSaveMessage((error as Error).message); } };
  useEffect(() => { if (!applyJob || ["succeeded", "failed", "cancelled", "interrupted"].includes(applyJob.state)) return; const timer = setTimeout(async () => { try { const result = await api<{ job: ApplyJob; outcome: ApplyOutcome }>(`/api/systems/${new URLSearchParams(location.search).get("system") || "iamps"}/apply-jobs/${applyJob.id}`); setApplyJob(result.job); setApplyOutcome(result.outcome); if (["succeeded", "failed", "cancelled", "interrupted"].includes(result.job.state)) await refresh(); } catch (error) { setSaveMessage((error as Error).message); } }, 1000); return () => clearTimeout(timer); }, [applyJob?.id, applyJob?.state]);
  const state = pipelineState(section); const parts = inspection.current.parts;
  return <aside className="section-workspace section-inspector" aria-label={`${section.visible_number} ${section.heading} workspace`}><header><div><span>{inspection.identity.stable_id} · {inspection.identity.stable_key}</span><h2>{inspection.identity.visible_number} {inspection.identity.heading}</h2></div><button aria-label="Close section workspace" onClick={safeClose}>×</button></header><div className="inspector-columns">
    <section className="inspector-current"><header><span>Current document</span><Status value={inspection.current.status.state} /></header>{parts.map((part, index) => <article key={part.pid || part.table || index}><small>{part.pid || part.table || part.kind}</small>{part.current || part.text ? <p>{part.current || part.text}</p> : null}{part.requirements?.map((req: any) => <div className="requirement" key={req.id}><b>{req.id}</b><span>{req.text}</span><Status value={req.rating || "unrated"} /></div>)}{part.row_texts?.map((row: string, i: number) => <p key={i}>{row}</p>)}</article>)}{inspection.removed.length > 0 && <div className="removed-content"><strong>Tracked deletions — not current text</strong>{inspection.removed.map((item, i) => <p key={`${item.paragraph_id}-${i}`}>{item.text}</p>)}</div>}</section>
    <section className="inspector-proposal"><header><span>Proposed change and brief</span><div className="proposal-mode"><button className={!previewMode ? "active" : ""} onClick={() => setPreviewMode(false)}>Edit</button><button className={previewMode ? "active" : ""} onClick={() => setPreviewMode(true)}>Preview</button></div></header>{proposal?.approved && <div className="approval-warning" role="status"><strong>Approved version</strong><span>{proposal.approval_warning}</span></div>}{!proposal ? <Empty title="No editable proposal exists" text="The framework has not selected a proposal or section file for this section." /> : proposal.lane === "build" ? previewMode ? <pre className="proposal-preview">{proposal.content}</pre> : <textarea className="proposal-editor" aria-label="Build section draft" value={proposal.content || ""} onChange={event => { setProposal({ ...proposal, content: event.target.value }); invalidate(); }} /> : previewMode ? <div className="change-preview">{proposal.records.map(record => <article key={record.edit_id}><b>{record.edit_id} — {record.title}</b><small>{record.operation} at {record.target}</small><p>{record.replacement}</p><footer>{record.evidence_ids.join(", ") || "No evidence selected"}</footer></article>)}</div> : <div className="change-sheet">{proposal.records.map((record, index) => { const findings = validationResult?.findings.filter(finding => finding.record_id === record.edit_id) || []; return <fieldset key={`${record.edit_id}-${index}`}><legend>{record.edit_id || `Change ${index + 1}`}</legend>{findings.length > 0 && <div className="wide validation-findings" role="status">{findings.map((finding, i) => <p key={`${finding.code}-${i}`}><Status value={finding.severity} /><b>{finding.field || finding.code}</b>{finding.message}</p>)}</div>}<label>Edit ID<input value={record.edit_id} onChange={event => changeRecord(index, "edit_id", event.target.value)} /></label><label>Change title<input value={record.title} onChange={event => changeRecord(index, "title", event.target.value)} /></label><label>Stable target<select value={record.target} onChange={event => changeRecord(index, "target", event.target.value)}>{proposal.stable_ids.map(id => <option key={id}>{id}</option>)}</select></label><label>Operation<select value={record.operation} onChange={event => changeRecord(index, "operation", event.target.value)}>{["Replace", "Insert before", "Insert after", "Delete", "Replace table content"].map(value => <option key={value}>{value}</option>)}</select></label><label className="wide">Replacement text or table<textarea rows={6} value={record.replacement} onChange={event => changeRecord(index, "replacement", event.target.value)} /></label><label className="wide">Observed facts<textarea rows={3} value={record.facts} onChange={event => changeRecord(index, "facts", event.target.value)} /></label><label className="wide">Why this change is required<textarea rows={3} value={record.rationale} onChange={event => changeRecord(index, "rationale", event.target.value)} /></label><div className="evidence-picker wide"><strong>Evidence attached to the change record</strong>{inspection.evidence.map(row => <label key={row.evidence_id}><input type="checkbox" checked={record.evidence_ids.includes(row.evidence_id)} onChange={event => changeRecord(index, "evidence_ids", event.target.checked ? [...record.evidence_ids, row.evidence_id] : record.evidence_ids.filter(id => id !== row.evidence_id))} /><span><b>{row.evidence_id}</b>{row.claim || row.question}</span><button type="button" onClick={() => openEvidence(row)}>Read source</button></label>)}</div></fieldset>})}<button className="add-change" onClick={addRecord}>Add change {proposal.next_edit_id}</button></div>}{validationResult && validationResult.findings.some(finding => !finding.record_id) && <div className="validation-findings" role="status">{validationResult.findings.filter(finding => !finding.record_id).map((finding, i) => <p key={`${finding.code}-${i}`}><Status value={finding.severity} /><b>{finding.code}</b>{finding.message}</p>)}</div>}{inspection.open_questions.length > 0 && <div className="brief-questions"><strong>Questions still to answer</strong>{inspection.open_questions.map((q, i) => <p key={q.id || i}>{q.question}</p>)}</div>}{inspection.comments.map((comment, i) => <blockquote key={i}><b>{comment.author || "Reviewer"}</b>{comment.text}</blockquote>)}</section>
    <section className="inspector-evidence"><header><span>Supporting evidence</span><b>{inspection.evidence.length}</b></header>{inspection.evidence.length ? inspection.evidence.map(row => <button key={row.evidence_id} onClick={() => openEvidence(row)}><span className="evidence-id">{row.evidence_id}</span><Status value={row.status} /><strong>{row.claim || row.question}</strong><small>{row.source_title || "Source unavailable"}</small></button>) : <Empty title="Evidence is still open" text="No reviewed matrix claim is linked to this section. Treat the section as a question, not a conclusion." />}</section>
  </div>{applyOutcome && <div className="apply-outcome" role="status"><strong>{human(applyOutcome.state)}</strong><span>Applied: {applyOutcome.applied.join(", ") || "none"}</span><span>Already applied: {applyOutcome.already_applied.join(", ") || "none"}</span><span>Blocked: {applyOutcome.blocked.join(", ") || "none"}</span>{applyOutcome.backup && <small>Backup: {applyOutcome.backup}</small>}{applyOutcome.state === "partial" && <button onClick={prepareApply}>Resume remaining edits</button>}</div>}<footer className="proposal-instrument"><div><small>{proposal?.file || inspection.work.change_file || inspection.work.section_file || "No proposal or build file is recorded."}</small>{saveMessage && <strong role="status">{saveMessage}</strong>}</div>{applyJob && <span>{human(applyJob.state)}{applyJob.message ? `: ${applyJob.message}` : ""}</span>}{validationResult ? <span><b>{validationResult.errors} errors</b> · {validationResult.warnings} warnings</span> : <span>Not validated</span>}<button disabled={!proposal || dirty || validating} onClick={validateProposal}>{validating ? "Validating…" : "Validate"}</button><button disabled={!proposal || !dirty} onClick={saveProposal}>Save draft</button><button onClick={prepareApply} disabled={!proposal || dirty || !validationResult?.valid || validationResult.file_hash !== proposal.etag || snapshot.word_locked || proposal.section.stable_key !== inspection.identity.stable_key || Boolean(applyJob && !["succeeded", "failed", "cancelled", "interrupted"].includes(applyJob.state))}>Apply proposal</button></footer>{applyPlan && <div className="scrim"><section className="apply-confirm"><header><h2>Confirm document change</h2><button onClick={() => setApplyPlan(null)}>×</button></header><dl><div><dt>System</dt><dd>{applyPlan.system}</dd></div><div><dt>Document</dt><dd>{applyPlan.document}</dd></div><div><dt>Section</dt><dd>{applyPlan.section.visible_number} {applyPlan.section.heading}</dd></div><div><dt>Proposal</dt><dd>{applyPlan.proposal}</dd></div><div><dt>Tracked edits</dt><dd>{applyPlan.edit_count}</dd></div></dl><p>The framework will create a backup and apply these as tracked changes. This confirmation is separate from viewing or validating the proposal.</p><footer><button className="quiet" onClick={() => setApplyPlan(null)}>Cancel</button><button onClick={confirmApply}>Apply {applyPlan.edit_count} edits</button></footer></section></div>}</aside>;
}

function AssessmentReader({ info, preview, revisions, comments, reload, back }: { info: DocumentInfo | null; preview: DocumentPreview | null; revisions: RevisionView | null; comments: DocumentComment[]; reload: () => void; back: () => void }) {
  const [mode, setMode] = useState<"pages" | "changes" | "comments">("pages"); const [page, setPage] = useState(1);
  if (!info) return <section className="page assessment-page"><Loading /></section>;
  if (info.state !== "ready") return <section className="page assessment-page"><button className="back-link" onClick={back}>Back to section map</button><header className="page-heading"><div><span>Authoritative assessment</span><h1>Document selection is blocked</h1><p>{info.reason}</p></div><button onClick={reload}>Check again</button></header><div className="document-blocker"><strong>Resolve these candidates before editing</strong>{info.candidates?.length ? info.candidates.map(path => <code key={path}>{path}</code>) : <p>No working DOCX was found beside an active change record.</p>}</div></section>;
  const warning = preview && (!preview.revisions_in_pdf || !preview.comments_in_pdf);
  return <section className="page assessment-page"><button className="back-link" onClick={back}>Back to section map</button><header className="page-heading assessment-heading"><div><span>Authoritative assessment</span><h1>{info.filename}</h1><p>Read the current document and its review signals before deciding whether work is ready to progress.</p></div><Status value={info.word_locked ? "open in Word" : "available"} /></header>
    <div className="document-facts"><div><span>Document status</span><strong>{info.properties?.status || "Not recorded"}</strong><small>Version {info.properties?.version || info.properties?.revision || "unknown"}</small></div><div><span>Tracked changes</span><strong>{info.tracked_changes?.total || 0}</strong><small>{info.tracked_changes?.insertions || 0} insertions · {info.tracked_changes?.deletions || 0} deletions</small></div><div><span>Reviewer comments</span><strong>{info.comment_count || 0}</strong><small>Comments requiring context</small></div><div><span>Manifest</span><strong>{human(info.manifest?.state || "unknown")}</strong><small>{info.word_locked ? `Word lock: ${info.word_lock_file}` : `${bytes(info.size || 0)} · safe to read`}</small></div></div>
    {warning && <div className="representation-warning"><strong>Rendered pages are not the approval record.</strong><span>The PDF may omit tracked-change markup or Word comments. Use “Changes” and “Comments” below before making an approval decision.</span></div>}
    <div className="document-desk"><aside><strong>Reading mode</strong><button className={mode === "pages" ? "active" : ""} onClick={() => setMode("pages")}>Rendered pages</button><button className={mode === "changes" ? "active" : ""} onClick={() => setMode("changes")}>Changes <span>{info.tracked_changes?.total || 0}</span></button><button className={mode === "comments" ? "active" : ""} onClick={() => setMode("comments")}>Comments <span>{comments.length}</span></button>{mode === "changes" && revisions?.sections.length ? <><strong>Jump to section</strong>{revisions.sections.map(section => <button key={`${section.index}-${section.title}`} onClick={() => globalThis.document.getElementById(`revision-${section.index}`)?.scrollIntoView()}>{section.title}</button>)}</> : null}</aside><div className="document-reader">{mode === "pages" ? <>{preview?.pdf_url ? <><div className="page-controls"><button disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))}>Previous</button><span>Page {page}{preview.page_count ? ` of ${preview.page_count}` : ""}</span><button disabled={Boolean(preview.page_count && page >= preview.page_count)} onClick={() => setPage(p => p + 1)}>Next</button></div><iframe title="Current assessment document" src={`${preview.pdf_url}#page=${page}&toolbar=0`} /></> : <Empty title={preview?.state === "unavailable" ? "Rendered preview unavailable" : "Preparing document preview"} text={preview?.reason || "The local renderer is creating the first cached page view. Changes and comments remain available."} />}</> : mode === "changes" ? <div className="revision-view"><p>{revisions?.notice}</p>{revisions?.paragraphs.map(paragraph => <div id={`revision-${paragraph.index}`} key={paragraph.index} className={paragraph.style.toLowerCase().startsWith("heading") ? "revision-heading" : ""}>{paragraph.tokens.map((token, i) => <span key={i} className={`revision-${token.kind}`}>{token.text}</span>)}</div>)}</div> : <div className="comment-view">{comments.length ? comments.map(comment => <article key={comment.id}><header><strong>{comment.author || "Reviewer"}</strong><span>{comment.date?.slice(0, 10) || "Date unavailable"}</span></header><p>{comment.text}</p><blockquote>{comment.anchored_text || "The commented text could not be resolved."}</blockquote></article>) : <Empty title="No Word comments" text="The authoritative document contains no reviewer comments." />}</div>}</div></div>
  </section>;
}

function ApplicationPortrait({ portrait, summary, openEvidence, investigate, navigate }: { portrait: Portrait | null; summary: Summary | null; openEvidence: (id: string) => void; investigate: (q: string) => void; navigate: (v: View) => void }) {
  const [areaKey, setAreaKey] = useState(""); if (!portrait || !summary) return <Loading />; const active = portrait.areas.find(x => x.key === areaKey) || portrait.areas[0]; const total = Math.max(1, portrait.assessment.total); const verified = portrait.assessment.status_counts.VERIFIED || 0; const unresolved = total - verified; const pending = portrait.assessment.review_counts.pending || 0;
  return <section className="page portrait-page"><header className="portrait-hero"><div className="application-core"><span>Application under assessment</span><h1>{portrait.application.name}</h1><p>{portrait.application.scope}</p><div><button onClick={() => navigate("evidence")}>Read supported claims</button><button className="quiet" onClick={() => navigate("sources")}>Inspect source coverage</button></div></div><div className="assessment-reading"><div className="reading-head"><div><span>What the evidence currently supports</span><strong>{verified} of {total} claims are verified</strong></div><Status value={unresolved ? "attention required" : "supported"} /></div><div className="evidence-composition">{STATUSES.map(s => { const value = portrait.assessment.status_counts[s] || 0; return value ? <i key={s} className={`segment segment-${s.toLowerCase().replaceAll("_", "-")}`} style={{ width: `${value / total * 100}%` }} title={`${human(s)}: ${value}`} /> : null; })}</div><dl><div><dt>Supported statements</dt><dd>{verified}</dd></div><div><dt>Need qualification</dt><dd>{unresolved}</dd></div><div><dt>Awaiting review</dt><dd>{pending}</dd></div><div><dt>Observed hosts</dt><dd>{portrait.observed_hosts.length}</dd></div></dl><p>Counts describe the evidence record, not application health or compliance.</p></div></header>
    <div className="decision-banner"><div><strong>{portrait.attention.length}</strong><span><b>questions need an assessor’s decision</b><small>Resolve missing or conflicting evidence before using those statements.</small></span></div>{portrait.attention[0] && <button onClick={() => investigate(portrait.attention[0].question || portrait.attention[0].claim)}>Investigate the highest-priority question</button>}</div>
    <div className="portrait-grid"><section className="area-map"><header><div><h2>How well can we describe the application?</h2><p>Choose an area to see supported statements and their limits.</p></div></header><div>{portrait.areas.map(area => <button key={area.key} className={active?.key === area.key ? "active" : ""} onClick={() => setAreaKey(area.key)}><i className={`area-signal signal-${area.state}`} /><span><strong>{area.label}</strong><small>{area.counts.VERIFIED || 0} verified · {area.total - (area.counts.VERIFIED || 0)} qualified or open</small></span><b>{area.total}</b></button>)}</div></section>
      <section className="area-detail">{!active ? <Empty title="No claims recorded" text="Search the indexed sources and add reviewed evidence to begin the portrait." /> : <><header><div><span>Current-state narrative</span><h2>{active.label}</h2></div><Status value={active.state} /></header><div className="claim-thread">{active.claims.length ? active.claims.map(claim => <button key={claim.evidence_id} onClick={() => openEvidence(claim.evidence_id)}><span className="evidence-id">{claim.evidence_id}</span><span><strong>{claim.claim}</strong><small>Read the cited proof · {claim.source_title}</small></span></button>) : <p className="empty">No verified statement is recorded for this area.</p>}</div>{active.decisions.length > 0 && <div className="qualification"><strong>What limits this description</strong>{active.decisions.slice(0, 3).map(item => <div key={item.evidence_id}><Status value={item.status} /><span>{item.gap_or_action || item.question || item.claim}</span><button onClick={() => investigate(item.question || item.claim)}>Investigate</button></div>)}</div>}</>}</section></div>
    <section className="estate-strip"><header><div><h2>Observed application estate</h2><p>Hosts with current indexed captures, ordered by evidence breadth.</p></div><span>{portrait.observed_hosts.length} hosts</span></header><div className="host-rack">{[...portrait.observed_hosts].sort((a, b) => b.breadth - a.breadth).slice(0, 24).map(host => <div key={host.host}><strong>{host.host}</strong><span>{summary.families.map(f => <i key={f} className={host.families[f] ? "seen" : ""} title={`${f}: ${host.families[f] || 0}`} />)}</span><small>{host.breadth} of {summary.families.length} evidence families</small></div>)}</div><p className="disclaimer">{portrait.disclaimer}</p></section>
  </section>;
}

function SearchDesk({ data, matrix, index, openFile, openEvidence, prepare, close }: { data: SearchResponse; matrix?: SearchStage; index?: SearchStage; openFile: (id: number, a?: string) => void; openEvidence: (r: EvidenceRow) => void; prepare: (h: IndexHit) => void; close: () => void }) {
  const answered = matrix?.verdict === "LIKELY_ANSWERED"; return <section className="page search-page"><header className="search-heading"><button onClick={close}>Back to portrait</button><span>Evidence question</span><h1>{data.query}</h1><p>{answered ? "The matrix contains a likely answer. Read the cited source before reusing the claim." : "The matrix did not settle the question, so the workspace continued into captured data."}</p></header><div className="search-thread"><div className="stage"><b className="stage-marker">1</b><div className="stage-body"><header><div><span>First authority</span><h2>Reviewed evidence matrix</h2></div><Status value={matrix?.verdict} /></header>{!matrix?.matches?.length ? <p className="empty">No recorded claim answered this question.</p> : matrix.matches.map(row => <button className="evidence-row" key={row.evidence_id} onClick={() => openEvidence(row)}><span className="evidence-id">{row.evidence_id}</span><Status value={row.status} /><span><strong>{row.claim}</strong><small>{row.source_title} · {row.page_or_location}</small></span><b>Read proof</b></button>)}</div></div><div className={`stage ${index ? "" : "muted"}`}><b className="stage-marker">2</b><div className="stage-body"><header><div><span>Source discovery</span><h2>Captured system data</h2></div><span>{index ? `${index.results?.length || 0} matches` : "Not needed"}</span></header>{!index ? <p className="empty">Search stopped because the matrix likely answers the question.</p> : !index.results?.length ? <p className="empty">No indexed source matched. Review source coverage before concluding the information is absent.</p> : index.results.map((hit, i) => <article className="index-result" key={`${hit.rel_path}-${i}`}><div><b>{hit.host || "Project document"}</b>{hit.superseded && <Status value="superseded" />}</div><blockquote>{hit.evidence_excerpt}</blockquote><small>{hit.rel_path}<br />{hit.page_or_location}</small><footer><button disabled={!hit.file_id} onClick={() => hit.file_id && openFile(hit.file_id, hit.page_or_location)}>Read in source</button><button className="quiet" onClick={() => prepare(hit)}>Prepare reviewed claim</button></footer></article>)}</div></div></div></section>;
}

function EvidenceLedger({ rows, areas, openEvidence, investigate }: { rows: EvidenceRow[]; areas: Area[]; openEvidence: (r: EvidenceRow) => void; investigate: (q: string) => void }) {
  const [query, setQuery] = useState(""); const [status, setStatus] = useState(""); const [area, setArea] = useState(""); const visible = rows.filter(r => (!query || Object.values(r).join(" ").toLowerCase().includes(query.toLowerCase())) && (!status || r.status === status) && (!area || r.csa_area === area));
  return <section className="page ledger-page"><div className="page-heading"><div><span>Assessment assertions</span><h1>Claims and gaps</h1><p>Use verified claims to describe the application. Treat every other status as a qualification or an action.</p></div><div className="ledger-summary"><strong>{visible.length}</strong><span>claims in this view</span></div></div><div className="evidence-controls"><label>Find a claim<input value={query} onChange={e => setQuery(e.target.value)} placeholder="Question, claim or source" /></label><label>Evidence state<select value={status} onChange={e => setStatus(e.target.value)}><option value="">All states</option>{STATUSES.map(x => <option key={x}>{x}</option>)}</select></label><label>Assessment area<select value={area} onChange={e => setArea(e.target.value)}><option value="">All areas</option>{areas.map(x => <option value={x.key} key={x.key}>{x.label}</option>)}</select></label></div><div className="claim-ledger">{visible.map(row => <article key={row.evidence_id}><div className="claim-state"><span className="evidence-id">{row.evidence_id}</span><Status value={row.status} /><Status value={row.review_state} /></div><div className="claim-copy"><span>{human(row.csa_area || "unclassified")}</span><h2>{row.claim || row.question}</h2>{row.claim && row.question && <p>{row.question}</p>}<small>{row.source_title || "No source recorded"}{row.page_or_location ? ` · ${row.page_or_location}` : ""}</small>{row.gap_or_action && <div className="claim-action"><b>Action:</b> {row.gap_or_action}</div>}</div><div className="claim-buttons"><button onClick={() => openEvidence(row)} disabled={!row.source_title}>Read source</button>{row.status !== "VERIFIED" && <button className="quiet" onClick={() => investigate(row.question || row.claim)}>Investigate</button>}</div></article>)}</div>{!visible.length && <Empty title="No claims match this view" text="Change the filters or trace a new question." />}</section>;
}

function SourceCoverage({ summary, portrait, files, total, facets, controls, openFile }: { summary: Summary | null; portrait: Portrait | null; files: FileRow[]; total: number; facets: { statuses: string[]; extensions: string[]; source_classes: string[] }; controls: any; openFile: (id: number) => void }) {
  const [show, setShow] = useState(false); if (!summary || !portrait) return <Loading />; return <section className="page source-page"><div className="page-heading"><div><span>Observation boundary</span><h1>Source coverage</h1><p>Decide whether captures are sufficient before treating a gap as meaningful. Blank means “not observed”, not “does not exist”.</p></div><label className="history-toggle"><input type="checkbox" checked={controls.history} onChange={e => controls.setHistory(e.target.checked)} />Include superseded and archived</label></div><div className="source-health"><div><strong>{portrait.source_health.status_counts.indexed || 0}</strong><span>files can be searched</span></div><div><strong>{portrait.source_health.status_counts.skipped || 0}</strong><span>files were catalogued but not indexed</span></div><div><strong>{summary.current_captures}</strong><span>current captures define default scope</span></div></div>{portrait.source_health.skipped_reasons.length > 0 && <section className="skip-explainer"><header><h2>Why files were skipped</h2><p>Skipped files are known, but their content was not added to full-text search.</p></header><div>{portrait.source_health.skipped_reasons.map(x => <div key={x.reason}><span>{x.reason}</span><strong>{x.count}</strong></div>)}</div></section>}<section className="coverage-section"><header><div><h2>Host-by-evidence coverage</h2><p>Identify collection gaps before writing cross-host conclusions.</p></div><span>Current captures</span></header><div className="coverage-wrap"><table className="coverage"><thead><tr><th>Observed host</th>{summary.families.map(f => <th key={f}>{f}</th>)}</tr></thead><tbody>{summary.coverage.map(r => <tr key={r.host}><th>{r.host}</th>{summary.families.map(f => <td key={f} className={r.families[f] ? "has-data" : ""}>{r.families[f] || "—"}</td>)}</tr>)}</tbody></table></div></section><button className="disclosure" onClick={() => setShow(!show)}>{show ? "Hide individual files" : `Inspect ${total.toLocaleString()} files and index decisions`}</button>{show && <><div className="file-controls"><label>Find source<input value={controls.fileQuery} onChange={e => controls.setFileQuery(e.target.value)} /></label><label>Index state<select value={controls.fileStatus} onChange={e => controls.setFileStatus(e.target.value)}><option value="">All</option>{facets.statuses.map(x => <option key={x}>{x}</option>)}</select></label><label>File type<select value={controls.fileExt} onChange={e => controls.setFileExt(e.target.value)}><option value="">All</option>{facets.extensions.map(x => <option key={x}>{x || "text"}</option>)}</select></label><label>Source class<select value={controls.fileClass} onChange={e => controls.setFileClass(e.target.value)}><option value="">All</option>{facets.source_classes.map(x => <option key={x}>{x}</option>)}</select></label></div><div className="file-list">{files.map(file => <button key={file.file_id} onClick={() => openFile(file.file_id)}><span><strong>{file.rel_path.split("/").at(-1)}</strong><small>{file.host || "Project document"}<br />{file.rel_path}</small></span><code>{file.ext || "text"}</code><span><Status value={file.status} /><small>{file.reason}</small></span><b>{bytes(file.size)}</b></button>)}</div></>}</section>;
}

function Tables({ tables, rows, active, openTable }: { tables: TableInfo[]; rows: Record<string, unknown>[] | null; active: string; openTable: (n: string) => void }) {
  const columns = rows?.length ? Object.keys(rows[0]) : []; return <section className="page tables-page"><div className="page-heading"><div><span>Cross-host comparison</span><h1>Explore structured records</h1><p>Use question-shaped datasets to compare services, software, ports, identities or controls across the observed estate.</p></div></div><div className="table-browser"><div className="table-index">{tables.map(t => <button className={active === t.table ? "active" : ""} key={t.table} onClick={() => openTable(t.table)}><strong>{human(t.table)}</strong><span>{t.rows.toLocaleString()} records · {t.hosts} hosts</span><small>{t.columns.slice(0, 5).map(human).join(", ")}</small></button>)}</div><div className="table-data">{!rows ? <Empty title="Choose a comparison" text="Structured rows become evidence only after source and scope are reviewed." /> : !rows.length ? <Empty title="No records in scope" text="The current table returned no rows." /> : <><header><h2>{human(active)}</h2><strong>First {rows.length} rows</strong></header><div className="grid-scroll"><table><thead><tr>{columns.map(c => <th key={c}>{human(c)}</th>)}</tr></thead><tbody>{rows.map((r, i) => <tr key={i}>{columns.map(c => <td key={c}>{String(r[c] ?? "")}</td>)}</tr>)}</tbody></table></div></>}</div></div></section>;
}

function SourceReader({ preview, close }: { preview: Preview; close: () => void }) { return <aside className="reader open"><header><div><span>Exact source</span><strong>{preview.name}</strong><small>{preview.rel_path}</small></div><button onClick={close}>×</button></header><nav>{preview.pdf_url && <a href={preview.pdf_url} target="_blank">Rendered document</a>}{preview.raw_url && <a href={preview.raw_url} target="_blank">Original file</a>}<span>Cited lines are highlighted</span></nav><div className="reader-body">{preview.kind === "image" && preview.raw_url ? <img src={preview.raw_url} /> : preview.rows ? <table className="sheet"><tbody>{preview.rows.map((r, i) => <tr className={preview.row_start && i + preview.row_start === preview.highlight_row ? "highlight" : ""} key={i}><th>{(preview.row_start || 1) + i}</th>{r.map((c, j) => <td key={j}>{c}</td>)}</tr>)}</tbody></table> : preview.lines ? <div className="source-lines">{preview.lines.map(line => <div key={line.number} className={preview.highlight && line.number >= preview.highlight[0] && line.number <= preview.highlight[1] ? "highlight" : ""}><span>{line.number}</span><code>{line.text || " "}</code></div>)}</div> : <Empty title="Preview unavailable" text={preview.reason || "This format cannot be rendered safely."} />}</div></aside>; }

function DraftPanel({ draft, setDraft, result, validate, commit, close }: { draft: Draft; setDraft: (d: Draft) => void; result: Record<string, unknown> | null; validate: () => void; commit: () => void; close: () => void }) { const set = (k: keyof Draft, v: string) => setDraft({ ...draft, [k]: v }); return <div className="scrim"><section className="draft-panel"><header><div><span>Human review required</span><h2>Prepare an evidence claim</h2><p>Preserve the exact excerpt, then state one reusable claim.</p></div><button onClick={close}>×</button></header><div className="draft-grid"><label>Assessment area<input value={draft.csa_area} onChange={e => set("csa_area", e.target.value)} /></label><label>Evidence status<select value={draft.status} onChange={e => set("status", e.target.value)}>{STATUSES.map(x => <option key={x}>{x}</option>)}</select></label><label className="wide">Question<input value={draft.question} onChange={e => set("question", e.target.value)} /></label><label className="wide">Atomic claim<textarea rows={3} value={draft.claim} onChange={e => set("claim", e.target.value)} /></label><label className="wide">Source title<input value={draft.source_title} onChange={e => set("source_title", e.target.value)} /></label><label>Source version<input value={draft.source_version} onChange={e => set("source_version", e.target.value)} /></label><label>Exact location<input value={draft.page_or_location} onChange={e => set("page_or_location", e.target.value)} /></label><label className="wide">Supporting excerpt<textarea rows={4} value={draft.evidence_excerpt} onChange={e => set("evidence_excerpt", e.target.value)} /></label><label>Confidence<select value={draft.confidence} onChange={e => set("confidence", e.target.value)}>{["", "high", "medium", "low"].map(x => <option key={x}>{x}</option>)}</select></label><label>CSA section<input value={draft.section} onChange={e => set("section", e.target.value)} /></label><label className="wide">Inference reason<input value={draft.inference_reason} onChange={e => set("inference_reason", e.target.value)} /></label><label className="wide">Gap or action<input value={draft.gap_or_action} onChange={e => set("gap_or_action", e.target.value)} /></label></div>{result && <pre>{JSON.stringify(result, null, 2)}</pre>}<footer><button className="quiet" onClick={close}>Cancel</button><button onClick={validate}>Check claim</button><button disabled={!result || result.status !== "DRY_RUN"} onClick={commit}>Add reviewed claim</button></footer></section></div>; }
function SourceChooser({ row, files, choose, close }: { row: EvidenceRow; files: FileRow[]; choose: (f: FileRow) => void; close: () => void }) { return <div className="scrim"><section className="source-chooser"><header><div><span>Source ambiguity</span><h2>Choose the cited capture</h2><p>{row.evidence_id} names a file in more than one capture.</p></div><button onClick={close}>×</button></header>{files.map(f => <button key={f.file_id} onClick={() => choose(f)}><strong>{f.rel_path.split("/").at(-1)}</strong><span>{f.host || "Project document"}</span><small>{f.rel_path}</small></button>)}</section></div>; }
function Empty({ title, text }: { title: string; text: string }) { return <div className="empty-state"><strong>{title}</strong><p>{text}</p></div>; }
function Loading() { return <div className="loading"><span /><strong>Building the application portrait from evidence…</strong></div>; }
